package com.strikermall;
import java.util.*;
/** Small dependency-free JSON encoder/decoder for our own API. */
public final class Json {
 private final String s; private int pos;
 private Json(String s){this.s=s;}
 public static Object parse(String s){Json p=new Json(s);Object v=p.value();p.ws();if(p.pos!=s.length())throw new IllegalArgumentException("Invalid JSON");return v;}
 private void ws(){while(pos<s.length()&&Character.isWhitespace(s.charAt(pos)))pos++;}
 private char peek(){ws();if(pos>=s.length())throw new IllegalArgumentException("Invalid JSON");return s.charAt(pos);}
 private boolean take(char c){ws();if(pos<s.length()&&s.charAt(pos)==c){pos++;return true;}return false;}
 private Object value(){char c=peek();if(c=='"')return string();if(c=='{')return object();if(c=='[')return array();if(s.startsWith("true",pos)){pos+=4;return true;}if(s.startsWith("false",pos)){pos+=5;return false;}if(s.startsWith("null",pos)){pos+=4;return null;}int start=pos;while(pos<s.length()&&"0123456789+-.eE".indexOf(s.charAt(pos))>=0)pos++;if(start==pos)throw new IllegalArgumentException("Invalid JSON");return new java.math.BigDecimal(s.substring(start,pos));}
 private String string(){if(!take('"'))throw new IllegalArgumentException("Invalid string");StringBuilder b=new StringBuilder();while(pos<s.length()){char c=s.charAt(pos++);if(c=='"')return b.toString();if(c=='\\'){if(pos>=s.length())break;char d=s.charAt(pos++);switch(d){case 'n':b.append('\n');break;case 'r':b.append('\r');break;case 't':b.append('\t');break;case 'b':b.append('\b');break;case 'f':b.append('\f');break;case '"':b.append('"');break;case '\\':b.append('\\');break;case '/':b.append('/');break;case 'u': if(pos+4>s.length())throw new IllegalArgumentException("Invalid Unicode escape");b.append((char)Integer.parseInt(s.substring(pos,pos+4),16));pos+=4;break;default:throw new IllegalArgumentException("Invalid escape");}}else{if(c<32)throw new IllegalArgumentException("Invalid string");b.append(c);}}throw new IllegalArgumentException("Unterminated string");}
 private Map<String,Object> object(){take('{');Map<String,Object> o=new LinkedHashMap<>();if(take('}'))return o;do{String k=string();if(!take(':'))throw new IllegalArgumentException("Expected colon");o.put(k,value());if(take('}'))return o;}while(take(','));throw new IllegalArgumentException("Invalid object");}
 private List<Object> array(){take('[');List<Object> a=new ArrayList<>();if(take(']'))return a;do{a.add(value());if(take(']'))return a;}while(take(','));throw new IllegalArgumentException("Invalid array");}
 public static String encode(Object v){if(v==null)return "null";if(v instanceof Number || v instanceof Boolean)return v.toString();if(v instanceof Map<?,?>){List<String> a=new ArrayList<>();for(var e:((Map<?,?>)v).entrySet())a.add(encode(String.valueOf(e.getKey()))+":"+encode(e.getValue()));return "{"+String.join(",",a)+"}";}if(v instanceof Iterable<?>){List<String> a=new ArrayList<>();for(Object x:(Iterable<?>)v)a.add(encode(x));return "["+String.join(",",a)+"]";}String s=v.toString();StringBuilder b=new StringBuilder("\"");for(char c:s.toCharArray()){switch(c){case '"':b.append("\\\"");break;case '\\':b.append("\\\\");break;case '\n':b.append("\\n");break;case '\r':b.append("\\r");break;case '\t':b.append("\\t");break;default:if(c<32)b.append(String.format("\\u%04x",(int)c));else b.append(c);}}return b.append('"').toString();}
}
